import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from candlestick ----
type Candle = { date: Date; open: number; high: number; low: number; close: number };

const TRADING_DAYS = 90;

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

/** Only weekdays enter the series, so a band scale over its index has no weekend gaps. */
function nextWeekday(date: Date): Date {
  const next = new Date(date);
  next.setUTCDate(next.getUTCDate() + 1);
  while (next.getUTCDay() === 0 || next.getUTCDay() === 6) {
    next.setUTCDate(next.getUTCDate() + 1);
  }
  return next;
}

/** Synthetic daily OHLC: a random-walk close with independent up/down wicks per day. */
const candles: Candle[] = (() => {
  const result: Candle[] = [];
  let date = new Date(Date.UTC(2024, 0, 2)); // a Tuesday
  let close = 150;
  for (let i = 0; i < TRADING_DAYS; i++) {
    const open = close;
    const drift = (random() - 0.5) * 6;
    close = Math.max(20, open + drift);
    const wickUp = random() * 3 + 0.5;
    const wickDown = random() * 3 + 0.5;
    const high = Math.max(open, close) + wickUp;
    const low = Math.min(open, close) - wickDown;
    result.push({ date, open, high, low, close });
    date = nextWeekday(date);
  }
  return result;
})();

const MARGIN = { top: 16, right: 20, bottom: 36, left: 56 };
const GAIN = d3.schemeRdYlGn[3][2];
const LOSS = d3.schemeRdYlGn[3][0];

/** One open-high-low-close bar per trading day, in chronological order. */
export type Data = { date: Date; open: number; high: number; low: number; close: number }[];

export default function CandlestickChart({ data = candles, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // A band scale over trading-day index, not a time scale, so weekends leave no gap.
  const x = useMemo(
    () =>
      d3
        .scaleBand()
        .domain(data.map((_, i) => String(i)))
        .range([0, innerWidth])
        .padding(0.25),
    [data, innerWidth]
  );

  const y = useMemo(() => {
    const low = d3.min(data, (d) => d.low) ?? 0;
    const high = d3.max(data, (d) => d.high) ?? 1;
    return d3.scaleLinear().domain([low, high]).nice().range([innerHeight, 0]);
  }, [data, innerHeight]);

  const xTicks: Tick[] = useMemo(() => {
    const step = Math.max(1, Math.round(data.length / 8));
    const ticks: Tick[] = [];
    data.forEach((d, i) => {
      if (i % step !== 0) return;
      const offset = x(String(i));
      if (offset === undefined) return;
      ticks.push({ value: d3.utcFormat('%b %-d')(d.date), offset: offset + x.bandwidth() / 2 });
    });
    return ticks;
  }, [data, x]);

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('$.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const bandwidth = x.bandwidth();

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label={`Candlestick chart of daily open, high, low and close over ${data.length} trading days`}>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {data.map((d, i) => {
          const cx = (x(String(i)) ?? 0) + bandwidth / 2;
          const color = d.close >= d.open ? GAIN : LOSS;
          const bodyTop = y(Math.max(d.open, d.close));
          const bodyBottom = y(Math.min(d.open, d.close));
          return (
            <g key={d.date.toISOString()}>
              <line x1={cx} x2={cx} y1={y(d.high)} y2={y(d.low)}
                    stroke={color} strokeWidth={1} strokeLinecap="round" />
              <rect x={cx - bandwidth / 2} y={bodyTop}
                    width={bandwidth} height={Math.max(1, bodyBottom - bodyTop)}
                    fill={color} />
            </g>
          );
        })}
      </g>
    </svg>
  );
}
